char bit;
while (infile.read(&bit, 1)) {
    if (bit == '0') {
        if (!root->left) {
            root->left = std::make_shared<Node>('+', 0);
        }
        root = root->left;
    } else if (bit == '1') {
        if (!root->right) {
            root->right = std::make_shared<Node>('+', 0);
        }
        root = root->right;
    }
}
char symbol;
if (infile.read(&symbol, 1)) {
    root->data = symbol;
    root->frequency = 0;
}

